#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# ──────────────────────────────────────────────────────────────────────────
# STAGES: shutdown of AI Profile Photo Maker.
# Runbook this automates: docs/operations/SHUTDOWN-CHECKLIST.md
#
#   scripts/shutdown/shutdown-wizard.sh            # real run
#   DRY_RUN=1 scripts/shutdown/shutdown-wizard.sh  # reads everything, changes nothing
#
# Safe to stop and re-run: finished stages are remembered and offered as skips.
# Non-secret state lives in ~/.local/state/aipm-shutdown/ (never in the repo).
# API keys are read from the running Azure app into memory only.
# ──────────────────────────────────────────────────────────────────────────

TOTAL_STAGES=14

REPO="alanw707/AI.ProfilePhotoMaker"
RG="aiprofilemaker-v1"
API_APP="aipm-api-v1"
DOMAIN="aiprofilephotomaker.com"
REPLICATE_OWNER="alanw707"
WEB_APP="aipm-web-v1"
DRY_RUN="${DRY_RUN:-0}"

SCRIPT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
SITE_DIR="$SCRIPT_DIR/showcase"
STATE_DIR="${AIPM_SHUTDOWN_STATE:-$HOME/.local/state/aipm-shutdown}"
AZ_CFG="$STATE_DIR/azure-cli"
mkdir -p "$STATE_DIR" "$AZ_CFG"
chmod 700 "$STATE_DIR"
ENV_FILE="$STATE_DIR/state.env"
BACKUP_DIR="$STATE_DIR/backup"
mkdir -p "$BACKUP_DIR"

# Secrets: memory only, filled from the Azure app (stage 3) or asked on demand.
STRIPE_KEY=""; REPLICATE_TOKEN=""; POSTMARK_TOKEN=""; SQL_CONN=""
SQL_SERVER_FQDN=""; SQL_SERVER=""; SQL_DB="aipmdb"; SQL_PASS=""; STORAGE_ACCOUNT=""
DONE_NOW=(); PARTIAL=0

set -E
trap 'printf "\n"; warn "Stopped on an error (line $LINENO). Nothing after this point ran. Fix it and re-run; finished stages are remembered."' ERR

# ── helpers (stage-level, below the marker) ─────────────────────────────────

yes_default() { local r=""; printf '  %s? %s [Y/n] ' "$YELLOW" "$1"; read -r r || true; [[ ! "$r" =~ ^[Nn] ]]; }
ok()   { printf '  %s✓%s %s\n' "$GREEN" "$RESET" "$1"; }
fail() { printf '  %s✗ %s%s\n' "$RED" "$1" "$RESET"; }
todo() { SKIPPED+=("$1"); PARTIAL=1; }

# act "description" cmd... runs a command that changes something, or only
# prints it in dry-run mode.
act() {
  local desc="$1"; shift
  if [[ "$DRY_RUN" == 1 ]]; then note "[dry run] would: $desc"; return 0; fi
  "$@"
}

# az runs the Azure CLI. Uses a local install if present, otherwise the
# official Docker image with its login kept in $AZ_CFG.
AZ_NATIVE="$(type -P az || true)"
# Where az writes downloads: the real dir natively, the mounted /backup in Docker.
if [[ -n "$AZ_NATIVE" ]]; then AZ_BACKUP_DIR="$BACKUP_DIR"; else AZ_BACKUP_DIR="/backup"; fi
az() {
  if [[ -n "$AZ_NATIVE" ]]; then "$AZ_NATIVE" "$@"; return; fi
  local tty=(-i); [[ -t 0 && -t 1 ]] && tty=(-it)
  docker run --rm "${tty[@]}" -v "$AZ_CFG":/root/.azure -v "$BACKUP_DIR":/backup \
    mcr.microsoft.com/azure-cli az "$@"
}
azq() { az "$@" 2>/dev/null | tr -d '\r'; }   # quiet, CR-stripped (docker -t adds \r)
rg_exists() { [[ "$(azq group exists -n "$RG")" == "true" ]]; }

# need VAR "prompt" asks for a secret only if it isn't already known.
need() { [[ -n "${!1}" ]] || ask_secret "$1" "$2"; }

stripe() { curl -gsS -u "$STRIPE_KEY:" "https://api.stripe.com/v1/$1" "${@:2}"; }
replicate() { curl -gsS -H "Authorization: Bearer $REPLICATE_TOKEN" "https://api.replicate.com/v1/$1" "${@:2}"; }

sqlq() { # sqlq "SQL" → rows separated by |
  docker run --rm -e SQLCMDPASSWORD="$SQL_PASS" mcr.microsoft.com/mssql-tools \
    /opt/mssql-tools/bin/sqlcmd -S "tcp:$SQL_SERVER_FQDN,1433" -d "$SQL_DB" -U sqladmin -N \
    -h -1 -W -s '|' -b -Q "SET NOCOUNT ON; $1" | tr -d '\r'
}

run_stage() { # run_stage KEY "Title" function
  local key="$1" title="$2" fn="$3" when
  stage "$title"
  when=$(_existing "DONE_$key" || true)
  if [[ -n "$when" ]]; then
    note "Already done ($when)."
    confirm "Run it again?" || return 0
  elif ! yes_default "Run this stage now? (n skips it for now)"; then
    todo "Stage skipped: $title"; return 0
  fi
  printf '\n'
  PARTIAL=0
  "$fn"
  if [[ "$PARTIAL" == 0 && "$DRY_RUN" != 1 ]]; then
    write_env "DONE_$key" "$(date +%F' '%H:%M)" >/dev/null; DONE_NOW+=("$title")
  fi
  printf '\n'; pause "Press Enter for the next stage"
}

# ── stages ──────────────────────────────────────────────────────────────────

s_preflight() {
  local missing=()
  for t in docker gh jq curl gpg; do command -v "$t" >/dev/null || missing+=("$t"); done
  if (( ${#missing[@]} )); then fail "Missing tools: ${missing[*]}. Install them and re-run."; exit 1; fi
  docker info >/dev/null 2>&1 || { fail "Docker isn't running. Start it (sudo systemctl start docker) and re-run."; exit 1; }
  gh auth status >/dev/null 2>&1 || { fail "GitHub CLI isn't signed in. Run: gh auth login"; exit 1; }
  if [[ -n "$AZ_NATIVE" ]]; then ok "Tools ready (Azure CLI: $AZ_NATIVE)."
  else ok "Tools ready (Azure CLI runs in Docker; first pull takes a minute)."; fi
  [[ "$DRY_RUN" == 1 ]] && warn "DRY RUN: nothing will be changed or deleted."

  say "Signing in to Azure. A code appears below: open the link, paste it, and sign in"
  say "with the account that owns the subscription."
  if ! azq account show -o none; then
    az config set extension.use_dynamic_install=yes_without_prompt >/dev/null 2>&1 || true
    az login --use-device-code -o none
  fi
  az config set extension.use_dynamic_install=yes_without_prompt >/dev/null 2>&1 || true
  ok "Azure: $(azq account show --query '[name, user.name]' -o tsv | paste -sd' ' -)"
  if rg_exists; then
    ok "Resource group $RG is running. Its resources:"
    az resource list -g "$RG" --query '[].{name:name, type:type}' -o table 2>/dev/null | sed 's/^/    /'
  else
    warn "Resource group $RG doesn't exist (already deleted?). Azure stages will be skipped."
  fi
  say ""
  say "Note today's cost so you can confirm it drops later:"
  open_url "https://portal.azure.com/#view/Microsoft_Azure_CostManagement/Menu/~/costanalysis"
}

s_pipeline() {
  say "The deploy workflow runs on every push to main and recreates the Azure"
  say "resource group if it's missing. Disabling it first stops that."
  local state; state=$(gh api "repos/$REPO/actions/workflows/simple-deploy.yml" -q .state 2>/dev/null || echo unknown)
  note "Current state: $state"
  if [[ "$state" == "disabled_manually" ]]; then ok "Already disabled."; return; fi
  act "disable workflow simple-deploy.yml" gh workflow disable simple-deploy.yml -R "$REPO"
  ok "Deploy workflow disabled (re-enable any time with: gh workflow enable simple-deploy.yml -R $REPO)."
  local pr; pr=$(gh pr list -R "$REPO" --state open --json number,title -q '.[] | "#\(.number) \(.title)"' 2>/dev/null || true)
  if [[ -n "$pr" ]]; then note "Open PRs (leave or close them; nothing will deploy now):"; printf '%s\n' "$pr" | sed 's/^/    /'; fi
}

s_keys() {
  # Not persisted on purpose: keys stay in memory for this run only.
  if ! rg_exists; then
    warn "Azure is gone, so keys can't be read from the app. Later stages will ask for any they need."
    return
  fi
  local js
  js=$(azq containerapp secret list -n "$API_APP" -g "$RG" --show-values -o json) || { fail "Couldn't read the app's secrets."; todo "Read app keys"; return; }
  sec() { jq -r --arg n "$1" '.[] | select(.name==$n) | .value // empty' <<<"$js"; }
  STRIPE_KEY=$(sec stripe-secret-key); REPLICATE_TOKEN=$(sec replicate-token)
  POSTMARK_TOKEN=$(sec postmark-server-token); SQL_CONN=$(sec connection-string)
  SQL_PASS=$(sed -n 's/.*Password=\([^;]*\);.*/\1/p' <<<"$SQL_CONN")
  SQL_SERVER_FQDN=$(sed -n 's/.*Server=tcp:\([^,;]*\).*/\1/p' <<<"$SQL_CONN")
  SQL_SERVER="${SQL_SERVER_FQDN%%.*}"
  STORAGE_ACCOUNT=$(azq storage account list -g "$RG" --query '[0].name' -o tsv)
  for v in STRIPE_KEY REPLICATE_TOKEN POSTMARK_TOKEN SQL_PASS; do
    if [[ -n "${!v}" ]]; then ok "$v loaded"; else warn "$v not found; you'll be asked for it when needed."; fi
  done
  note "SQL server: ${SQL_SERVER:-?}  Storage: ${STORAGE_ACCOUNT:-?}"
  write_env SQL_SERVER_FQDN "$SQL_SERVER_FQDN" >/dev/null
  write_env STORAGE_ACCOUNT "$STORAGE_ACCOUNT" >/dev/null
}

s_inventory() {
  rg_exists || { warn "Azure is gone; nothing to count."; return; }
  [[ -n "$SQL_PASS" && -n "$SQL_SERVER" ]] || { fail "Database password not loaded (stage 3)."; todo "User inventory"; return; }
  local ip; ip=$(curl -fsS --max-time 10 https://api.ipify.org)
  say "Opening the database firewall to this machine ($ip) for the read-only queries."
  az sql server firewall-rule create -g "$RG" -s "$SQL_SERVER" -n shutdown-wizard \
    --start-ip-address "$ip" --end-ip-address "$ip" -o none
  local counts
  counts=$(sqlq "SELECT 'Accounts', COUNT(*) FROM AspNetUsers;
SELECT 'Verified emails', COUNT(*) FROM AspNetUsers WHERE EmailConfirmed=1;
SELECT 'Accounts in last 90 days', COUNT(*) FROM AspNetUsers WHERE CreatedAt > DATEADD(day,-90,SYSUTCDATETIME());
SELECT 'Payment records', COUNT(*) FROM PaymentTransactions;
SELECT 'Credit purchases', COUNT(*) FROM CreditPurchases;
SELECT 'Trained models', COUNT(*) FROM ModelCreationRequests WHERE ReplicateModelId IS NOT NULL;")
  printf '%s\n' "$counts" | awk -F'|' '{printf "    %-28s %s\n", $1, $2}'
  USER_COUNT=$(awk -F'|' '$1=="Verified emails"{print $2}' <<<"$counts")
  write_env USER_COUNT "${USER_COUNT:-0}" >/dev/null

  sqlq "SELECT Email FROM AspNetUsers WHERE EmailConfirmed=1 AND Email IS NOT NULL;" \
    | grep '@' > "$STATE_DIR/user-emails.txt" || true
  chmod 600 "$STATE_DIR/user-emails.txt"
  sqlq "SELECT DISTINCT ReplicateModelId FROM ModelCreationRequests WHERE ReplicateModelId IS NOT NULL
UNION SELECT DISTINCT ModelName FROM ModelCreationRequests WHERE ModelName <> '';" \
    | sed 's/:.*//' | awk -v o="$REPLICATE_OWNER" 'NF{ if (index($0,"/")==0) $0=o"/"$0; print }' \
    | sort -u > "$STATE_DIR/replicate-models.txt" || true
  ok "Saved $(wc -l < "$STATE_DIR/user-emails.txt") email(s) and $(wc -l < "$STATE_DIR/replicate-models.txt") model name(s) to $STATE_DIR (private)."
  az sql server firewall-rule delete -g "$RG" -s "$SQL_SERVER" -n shutdown-wizard -o none || true
  ok "Firewall rule removed."
}

s_stripe() {
  need STRIPE_KEY "Stripe secret key (sk_live_…):"
  local acct; acct=$(stripe account | jq -r '.settings.dashboard.display_name // .email // .id // empty')
  [[ -n "$acct" ]] || { fail "Stripe rejected the key."; todo "Stripe cleanup"; return; }
  ok "Stripe account: $acct"

  local since; since=$(date -d '-60 days' +%s)
  local charges; charges=$(stripe "charges?limit=100&created[gte]=$since")
  local paid; paid=$(jq '[.data[] | select(.paid and (.refunded|not))] | length' <<<"$charges")
  local total; total=$(jq '[.data[] | select(.paid and (.refunded|not)) | .amount - .amount_refunded] | add // 0 | . / 100' <<<"$charges")
  say "Paid, unrefunded charges in the last 60 days: $paid (total \$$total)"
  if (( paid > 0 )); then
    jq -r '.data[] | select(.paid and (.refunded|not)) | "    \(.created|todate[:10])  $\(.amount/100)  \(.billing_details.email // .receipt_email // "-")  \(.id)"' <<<"$charges"
    if confirm "Refund all of these in full?"; then
      for id in $(jq -r '.data[] | select(.paid and (.refunded|not)) | .id' <<<"$charges"); do
        act "refund $id" stripe refunds -d charge="$id" -o /dev/null && ok "refunded $id"
      done
    else
      note "No refunds issued. You can refund individually in the dashboard:"
      open_url "https://dashboard.stripe.com/payments"
    fi
  fi

  local subs; subs=$(stripe "subscriptions?status=active&limit=100")
  local nsub; nsub=$(jq '.data | length' <<<"$subs")
  if (( nsub > 0 )); then
    warn "$nsub active subscription(s):"
    jq -r '.data[] | "    \(.id)  customer \(.customer)"' <<<"$subs"
    if confirm "Cancel all of them now (no further charges)?"; then
      for id in $(jq -r '.data[].id' <<<"$subs"); do act "cancel $id" stripe "subscriptions/$id" -X DELETE -o /dev/null && ok "cancelled $id"; done
    else todo "Cancel Stripe subscriptions"; fi
  else ok "No active subscriptions."; fi

  local hooks; hooks=$(stripe "webhook_endpoints?limit=100" | jq -r --arg d "$DOMAIN" '.data[]? | select(.url|contains($d)) | "\(.id) \(.url)"')
  if [[ -n "$hooks" ]]; then
    printf '%s\n' "$hooks" | sed 's/^/    /'
    if confirm "Delete these webhook endpoints?"; then
      while read -r id _; do act "delete webhook $id" stripe "webhook_endpoints/$id" -X DELETE -o /dev/null && ok "deleted $id"; done <<<"$hooks"
    else todo "Delete Stripe webhooks"; fi
  else ok "No webhooks point at $DOMAIN."; fi

  local links; links=$(stripe "payment_links?active=true&limit=100" | jq -r '.data[]?.id')
  local prods; prods=$(stripe "products?active=true&limit=100" | jq -r '.data[]? | "\(.id)\t\(.name)"')
  if [[ -n "$links$prods" ]]; then
    [[ -n "$prods" ]] && { say "Active products:"; printf '%s\n' "$prods" | sed 's/^/    /'; }
    [[ -n "$links" ]] && note "Active payment links: $(wc -w <<<"$links")"
    if confirm "Archive these products and deactivate the payment links? (reversible)"; then
      for id in $links; do act "deactivate $id" stripe "payment_links/$id" -d active=false -o /dev/null; done
      while IFS=$'\t' read -r id _; do [[ -n "$id" ]] && act "archive $id" stripe "products/$id" -d active=false -o /dev/null; done <<<"$prods"
      ok "Products archived."
    else todo "Archive Stripe products"; fi
  fi
}

s_notify() {
  local n="${USER_COUNT:-$(_existing USER_COUNT || echo '')}"
  local list="$STATE_DIR/user-emails.txt"
  if [[ ! -s "$list" ]]; then
    ok "No verified user emails on record (or stage 4 skipped). Nothing to send."; return
  fi
  n=$(wc -l < "$list")
  say "$n verified user(s) will get a short closing notice from no-reply@$DOMAIN."
  ask CLOSE_DATE "Closing date to announce (e.g. October 31, 2026):"
  ask CONTACT_EMAIL "Reply-to address for questions (e.g. your own email):"
  write_env CLOSE_DATE "$CLOSE_DATE" >/dev/null; write_env CONTACT_EMAIL "$CONTACT_EMAIL" >/dev/null
  local body
  body=$(cat <<EOF
Hello,

AI Profile Photo Maker is closing on $CLOSE_DATE.

What this means for you:
- The site and your account will stop working on that date.
- All uploaded photos, trained AI models, generated images and account data will be permanently deleted. Nothing is kept except records we must keep by law for payments.
- If you bought credits recently, you will receive a refund to your original payment method.

If you want to keep any of your headshots, sign in and download them before $CLOSE_DATE.

Thank you for trying it. Questions: reply to this email.

Alan Wang
AI Profile Photo Maker
EOF
)
  printf '\n%s\n\n' "$body" | sed 's/^/    │ /'
  confirm "Send this to all $n user(s) now?" || { todo "Email users"; return; }
  need POSTMARK_TOKEN "Postmark server token:"
  local batch sent=0
  while mapfile -t -n 500 chunk && (( ${#chunk[@]} )); do
    batch=$(printf '%s\n' "${chunk[@]}" | jq -R -s --arg b "$body" --arg r "$CONTACT_EMAIL" --arg f "AI Profile Photo Maker <no-reply@$DOMAIN>" \
      '[split("\n")[] | select(length>0) | {From:$f, To:., ReplyTo:$r, Subject:"AI Profile Photo Maker is closing", TextBody:$b, MessageStream:"outbound"}]')
    if [[ "$DRY_RUN" == 1 ]]; then note "[dry run] would send ${#chunk[@]} email(s)"; continue; fi
    curl -sS https://api.postmarkapp.com/email/batch -H "Accept: application/json" -H "Content-Type: application/json" \
      -H "X-Postmark-Server-Token: $POSTMARK_TOKEN" -d "$batch" > "$STATE_DIR/postmark-result.json"
    sent=$((sent + $(jq 'if type=="array" then [.[] | select(.ErrorCode==0)] | length else 0 end' "$STATE_DIR/postmark-result.json")))
  done < "$list"
  ok "Sent $sent of $n. Details: $STATE_DIR/postmark-result.json"
  (( sent == n )) || todo "Some closing emails failed (see postmark-result.json)"
  note "Give people until $CLOSE_DATE to download, then continue from stage 7."
}

s_backup() {
  rg_exists || { warn "Azure is gone; can't back up."; todo "DB backup"; return; }
  [[ -n "$SQL_PASS" && -n "$STORAGE_ACCOUNT" ]] || { fail "Database password or storage name not loaded (stage 3)."; todo "DB backup"; return; }
  local name key
  name="aipmdb-$(date +%F).bacpac"
  key=$(azq storage account keys list -n "$STORAGE_ACCOUNT" -g "$RG" --query '[0].value' -o tsv)
  act "create backup container" az storage container create -n backup --account-name "$STORAGE_ACCOUNT" --account-key "$key" -o none
  say "Exporting the database. This usually takes 5–15 minutes."
  act "export DB to $name" az sql db export -g "$RG" -s "$SQL_SERVER" -n "$SQL_DB" \
    --admin-user sqladmin --admin-password "$SQL_PASS" \
    --storage-key-type StorageAccessKey --storage-key "$key" \
    --storage-uri "https://$STORAGE_ACCOUNT.blob.core.windows.net/backup/$name" -o none
  act "download $name" az storage blob download -c backup -n "$name" -f "$AZ_BACKUP_DIR/$name" \
    --account-name "$STORAGE_ACCOUNT" --account-key "$key" -o none
  [[ "$DRY_RUN" == 1 ]] && return
  [[ -s "$BACKUP_DIR/$name" ]] || { fail "Download is missing or empty."; todo "DB backup"; return; }
  say "Encrypting the backup. Choose a passphrase and save it in your password manager."
  gpg --symmetric --cipher-algo AES256 -o "$BACKUP_DIR/$name.gpg" "$BACKUP_DIR/$name"
  [[ -s "$BACKUP_DIR/$name.gpg" ]] && rm -f "$BACKUP_DIR/$name"
  ok "Encrypted backup: $BACKUP_DIR/$name.gpg ($(du -h "$BACKUP_DIR/$name.gpg" | cut -f1))"
  write_env BACKUP_FILE "$BACKUP_DIR/$name.gpg" >/dev/null
  warn "Copy that file somewhere safe (cloud drive or password manager). It's the only copy once Azure is deleted."
  note "User photos are deliberately NOT backed up: the published policy promises they're deleted."
  pause "Press Enter once you've copied it somewhere safe"
}

s_replicate() {
  need REPLICATE_TOKEN "Replicate API token (r8_…):"
  local list="$STATE_DIR/replicate-models.txt"; touch "$list"
  say "Models from the database: $(wc -l < "$list")"
  say "Also check your Replicate models page for any the database missed:"
  open_url "https://replicate.com/$REPLICATE_OWNER"
  note "App-created models are named $REPLICATE_OWNER/user-<id>-<timestamp>."
  local extra
  ask extra "Paste extra model names (owner/name, space-separated), or Enter for none:"
  for m in $extra; do echo "$m" >> "$list"; done
  sort -u -o "$list" "$list"
  local models; models=$(grep -E "^$REPLICATE_OWNER/user-" "$list" || true)
  local others; others=$(grep -vE "^$REPLICATE_OWNER/user-" "$list" || true)
  [[ -n "$others" ]] && warn "Not deleting these (not app-named): $(paste -sd' ' <<<"$others")"
  [[ -n "$models" ]] || { ok "No app-created models to delete."; return; }
  printf '%s\n' "$models" | sed 's/^/    /'
  confirm "Permanently delete these $(wc -l <<<"$models") model(s) and all their versions?" || { todo "Delete Replicate models"; return; }
  local m v code
  while read -r m; do
    code=$(replicate "models/$m" -o /dev/null -w '%{http_code}')
    if [[ "$code" == 404 ]]; then note "$m already gone"; continue; fi
    for v in $(replicate "models/$m/versions" | jq -r '.results[]?.id'); do
      act "delete $m:$v" replicate "models/$m/versions/$v" -X DELETE -o /dev/null
    done
    if [[ "$DRY_RUN" == 1 ]]; then note "[dry run] would delete $m"; continue; fi
    code=$(replicate "models/$m" -X DELETE -o /dev/null -w '%{http_code}')
    if [[ "$code" =~ ^2 ]]; then ok "deleted $m"; else fail "$m: HTTP $code (delete it on the website)"; todo "Delete Replicate model $m by hand"; fi
  done <<<"$models"
  return 0
}

s_site() {
  [[ -f "$SITE_DIR/index.html" ]] || { fail "No page at $SITE_DIR/index.html"; todo "Showcase page"; return; }
  rg_exists || { fail "Resource group $RG is gone; the web app that serves the page no longer exists."; todo "Showcase page"; return; }
  say "The existing web app ($WEB_APP) will serve the project page in scripts/shutdown/showcase/."
  say "Its custom domain, managed certificate and Cloudflare DNS stay exactly as they are."
  say "Previewing it in your browser; edit index.html first if anything doesn't sound like you."
  open_url "file://$SITE_DIR/index.html"
  pause "Press Enter when the page is ready to publish"
  if [[ "$DRY_RUN" == 1 ]]; then DRY_RUN=1 "$SCRIPT_DIR/publish-showcase.sh"; return 0; fi
  confirm "Replace the live app on $DOMAIN with the project page now?" || { todo "Publish showcase"; return; }
  if "$SCRIPT_DIR/publish-showcase.sh"; then ok "Project page live at https://$DOMAIN"
  else fail "Publishing didn't verify; see the output above."; todo "Publish showcase"; fi
  return 0
}

s_domain() {
  local exp; exp=$(curl -sL --max-time 15 "https://rdap.org/domain/$DOMAIN" | jq -r '.events[]? | select(.eventAction=="expiration") | .eventDate[:10]')
  say "Registrar: GoDaddy. Paid through: ${exp:-unknown}."
  say "1) Turn on auto-renew so nobody can grab the name your LinkedIn links to:"
  open_url "https://dcc.godaddy.com/control/portfolio"
  step "My Products → Domains → $DOMAIN → Auto-renew: On."
  note "Optional, cheaper: transfer to Cloudflare Registrar (at cost, ~\$10/yr) from the Cloudflare dashboard → Domain Registration → Transfer."
  pause "Press Enter when auto-renew is on"
  say "2) Forward the site's addresses (privacy@, support@, legal@, security@) to your inbox:"
  open_url "https://dash.cloudflare.com/"
  step "$DOMAIN → Email → Email Routing → Get started / Enable."
  step "Destination addresses → add your own email, then click the link Cloudflare emails you."
  step "Routing rules → Catch-all address → Send to your email → Save."
  warn "If $DOMAIN currently has a mailbox elsewhere (e.g. GoDaddy email), enabling this replaces its MX records."
  pause "Press Enter when forwarding works (send yourself a test to privacy@$DOMAIN)"
  say "3) LinkedIn: change the entry to past tense with an end date (e.g. a Projects entry"
  say "   \"AI Profile Photo Maker, 2025–2026\"). The link can stay."
  open_url "https://www.linkedin.com/in/me/"
  pause "Press Enter when done (or to do it later)"
}

s_azure_delete() {
  rg_exists || { ok "Resource group $RG is already gone."; return; }
  local missing=()
  [[ -n "$(_existing BACKUP_FILE || true)" ]] || missing+=("database backup (stage 7)")
  [[ -n "$(_existing DONE_REPLICATE || true)" ]] || missing+=("Replicate cleanup (stage 8)")
  [[ -n "$(_existing DONE_SITE || true)" ]] || missing+=("project page (stage 9)")
  if (( ${#missing[@]} )); then
    warn "Not done yet: ${missing[*]}"
    confirm "Delete the Azure resources anyway?" || { todo "Delete Azure"; return; }
  fi
  # Everything except the web app, its environment and the apex domain's certificate.
  local keep="Microsoft.App/managedEnvironments|Microsoft.App/containerApps/$WEB_APP|managedCertificates/.*$DOMAIN-"
  local doomed; doomed=$(azq resource list -g "$RG" --query '[].id' -o tsv | grep -viE "/containerApps/$WEB_APP\$" \
    | grep -viE '/managedEnvironments/[^/]+$' | grep -viE "/managedCertificates/$DOMAIN-" || true)
  note "Kept: $keep"
  [[ -n "$doomed" ]] || { ok "Nothing left to delete."; return; }
  say "To delete:"
  # shellcheck disable=SC2001  # multi-line input
  sed 's#.*/providers/#    #' <<<"$doomed"
  warn "This permanently deletes the API, database, all user photos, registry, Key Vault and logs."
  local typed; ask typed "Type the resource group name ($RG) to confirm:"
  [[ "$typed" == "$RG" ]] || { note "Name didn't match; nothing deleted."; todo "Delete Azure"; return; }

  local env; env=$(azq containerapp env list -g "$RG" --query '[0].name' -o tsv)
  act "detach logs from $env" az containerapp env update -g "$RG" -n "$env" --logs-destination none -o none
  local id
  # Container apps/jobs and the api certificate first (they depend on the rest), then the others.
  while IFS= read -r id; do
    case "$id" in */containerApps/*|*/jobs/*|*/managedCertificates/*) ;; *) continue ;; esac
    if [[ "$id" == */managedCertificates/* ]]; then
      act "delete certificate ${id##*/}" az containerapp env certificate delete -g "$RG" -n "$env" --certificate "${id##*/}" --yes
    else act "delete ${id##*/providers/}" az resource delete --ids "$id"; fi
  done <<<"$doomed"
  while IFS= read -r id; do
    case "$id" in */containerApps/*|*/jobs/*|*/managedCertificates/*|*/databases/*) continue ;; esac
    if [[ "$id" == */Microsoft.OperationalInsights/workspaces/* ]]; then
      act "delete ${id##*/} (no soft delete)" az monitor log-analytics workspace delete -g "$RG" -n "${id##*/}" --force true --yes
    else act "delete ${id##*/providers/}" az resource delete --ids "$id"; fi
  done <<<"$doomed"
  local kv
  for kv in $(azq keyvault list-deleted --query "[?starts_with(name,'aipm-kv')].name" -o tsv); do
    act "purge Key Vault $kv" az keyvault purge -n "$kv" && ok "purged Key Vault $kv"
  done
  say "Left in $RG:"; az resource list -g "$RG" --query '[].[type,name]' -o tsv 2>/dev/null | sed 's/^/    /'

  say "GitHub deploy login (Entra app registration):"
  local app; app=$(azq ad app list --display-name ai-profile-photo-maker-deploy --query '[0].appId' -o tsv)
  if [[ -z "$app" ]]; then ok "    already gone"; return 0; fi
  local subs; subs=$(azq ad app federated-credential list --id "$app" --query '[].subject' -o tsv)
  note "    federated credentials: $(paste -sd' ' <<<"$subs")"
  if grep -qv "^repo:$REPO:" <<<"$subs"; then
    warn "    It trusts something besides $REPO; leaving it alone."; todo "Review app registration $app"; return 0
  fi
  az role assignment list --assignee "$app" --all --query '[].[roleDefinitionName,scope]' -o tsv 2>/dev/null | sed 's/^/    role: /'
  if confirm "Remove its role assignments and delete it?"; then
    for id in $(azq role assignment list --assignee "$app" --all --query '[].id' -o tsv); do act "remove role $id" az role assignment delete --ids "$id"; done
    act "delete app $app" az ad app delete --id "$app" && ok "deleted app registration"
  else todo "Delete app registration $app"; fi
  return 0
}

s_revoke() {
  say "The services are gone; revoke the keys they used. Each page opens in turn."
  open_url "https://platform.openai.com/api-keys";  step "OpenAI: delete the key used by the app."; pause
  open_url "https://replicate.com/account/api-tokens"; step "Replicate: revoke the app's token."; pause
  open_url "https://dashboard.stripe.com/apikeys"; step "Stripe: roll the secret key (keep the account for future projects)."; pause
  open_url "https://console.cloud.google.com/apis/credentials"; step "Google Cloud: delete the OAuth client for $DOMAIN."; pause
  open_url "https://account.postmarkapp.com/servers"; step "Postmark: delete or pause the server (the closing email has gone out)."; pause
  open_url "https://dash.cloudflare.com/?to=/:account/turnstile"; step "Cloudflare Turnstile: delete the widget."; pause
  note "Then remove the api.$DOMAIN DNS record at Cloudflare (it points at the deleted API app)."
}

s_gh_secrets() {
  local secrets vars
  secrets=$(gh secret list -R "$REPO" --json name -q '.[].name' 2>/dev/null || true)
  vars=$(gh variable list -R "$REPO" --json name -q '.[].name' 2>/dev/null || true)
  if [[ -z "$secrets$vars" ]]; then ok "No Actions secrets or variables left."; return; fi
  [[ -n "$secrets" ]] && { say "Secrets: $(paste -sd' ' <<<"$secrets")"; }
  [[ -n "$vars" ]] && { say "Variables: $(paste -sd' ' <<<"$vars")"; }
  confirm "Delete all of these from the repo?" || { todo "Remove GitHub secrets"; return; }
  local s
  for s in $secrets; do act "delete secret $s" gh secret delete "$s" -R "$REPO"; done
  for s in $vars; do act "delete variable $s" gh variable delete "$s" -R "$REPO"; done
  ok "Removed."
  note "The repo is public; consider scanning history for old leaks: docker run --rm -v \"\$PWD\":/r zricethezav/gitleaks detect -s /r"
}

s_verify() {
  local code
  code=$(curl -s -o /dev/null -w '%{http_code}' --max-time 15 "https://$DOMAIN" || true)
  if curl -s --max-time 15 "https://$DOMAIN" | grep -q "project archive"; then ok "$DOMAIN shows the project page."; else warn "$DOMAIN: HTTP $code, not the project page yet (DNS/certificates can take a while)."; fi
  if getent hosts "api.$DOMAIN" >/dev/null; then warn "api.$DOMAIN still resolves."; else ok "api.$DOMAIN no longer resolves."; fi
  local left; left=$(azq resource list -g "$RG" --query 'length(@)' -o tsv || echo '?')
  if [[ "$left" == 3 ]]; then ok "Azure: only the web app, its environment and the domain certificate remain."
  else warn "Azure: $left resource(s) in $RG (expected 3)."; fi
  say "Last: set a \$5/month budget alert so anything recreated by mistake gets noticed."
  open_url "https://portal.azure.com/#view/Microsoft_Azure_CostManagement/Menu/~/budgets"
  step "Add → Amount 5 → Alert at 100% actual → your email → Create."
  note "Check Cost analysis again in 2–3 days: daily cost should be \$0."
  pause "Press Enter when the budget is set"
}

# ── run ─────────────────────────────────────────────────────────────────────

banner "Shut down AI Profile Photo Maker"
note "State and backups: $STATE_DIR"
[[ "$DRY_RUN" == 1 ]] && warn "DRY RUN: reads everything and changes nothing, except a temporary database firewall rule it removes again."
pause "Continue?"

run_stage PREFLIGHT    "Check tools and sign in to Azure"           s_preflight
run_stage PIPELINE     "Stop the deploy pipeline"                   s_pipeline
stage "Load the app's keys from Azure (memory only)"; s_keys; pause "Press Enter for the next stage"
run_stage INVENTORY    "Count users, payments and trained models"   s_inventory
run_stage STRIPE       "Stripe: refunds, subscriptions, webhooks"   s_stripe
run_stage NOTIFY       "Email users about the closure"              s_notify
run_stage BACKUP       "Back up the database (encrypted)"           s_backup
run_stage REPLICATE    "Delete trained face models at Replicate"    s_replicate
run_stage SITE         "Serve the project page from the web app"    s_site
run_stage DOMAIN       "Keep the domain, forward its email"         s_domain
run_stage AZURE_DELETE "Delete the rest of Azure (irreversible)"    s_azure_delete
run_stage REVOKE       "Revoke the remaining API keys"              s_revoke
run_stage GH_SECRETS   "Remove GitHub Actions secrets"              s_gh_secrets
run_stage VERIFY       "Verify, and add a budget alert"             s_verify

_clear
if (( ${#SKIPPED[@]} )); then
  printf '\n%s%s  Shutdown paused with items left%s\n' "$BOLD" "$YELLOW" "$RESET"
  for s in "${SKIPPED[@]}"; do note "  - $s"; done
  note "Re-run the script to pick these up; finished stages are skipped."
else
  printf '\n%s%s  ✓ Shutdown complete%s\n' "$BOLD" "$GREEN" "$RESET"
fi
(( ${#DONE_NOW[@]} )) && note "Finished this run: ${#DONE_NOW[@]} stage(s)."
note "Backup: $(_existing BACKUP_FILE || echo 'none')"
note "Last step by hand: add \"Closed $(date +'%B %Y'). Kept for reference.\" to README.md."
printf '\n'
